"""Locked Talks N Walks monochrome logo asset.

Generated from the approved profile-picture logo and embedded as PNG data so
production builds do not depend on the historical illustration library.
"""

from __future__ import annotations

import base64
import io

from PIL import Image

_LOGO_PNG_B64 = """"""


def load_logo() -> Image.Image:
    return Image.open(io.BytesIO(base64.b64decode(_LOGO_PNG_B64))).convert("RGBA")
